// ============================================================
// Altamira Capital - Trade Entry Processor
// ============================================================
// Expected webhook payload:
// {
//   ticker: 'AAPL',
//   strategy: 'CSP',           // CSP, Momentum, Hedge, BullPutSpread, JadeLizard
//   direction: 'STO',          // STO (Sell to Open), BTO (Buy to Open), Long, Short
//   strike: 225,               // Strike price (options) or entry price (equity)
//   expiration: '2026-04-17',  // Options expiration date (YYYY-MM-DD)
//   delta: -0.22,              // Delta at entry
//   ivRank: 45,                // IV Rank at entry (0-100)
//   contracts: 1,              // Number of contracts or shares
//   entryPrice: 3.20,          // Premium received (credit) or paid (debit)
//   thesis: 'IV elevated...',  // Pre-trade thesis
//   edge: 'IV overpriced...'   // Edge description
// }
// ============================================================

const input = $input.first().json;

// -----------------------------------------------------------
// Validate required fields
// -----------------------------------------------------------
const requiredFields = ['ticker', 'strategy', 'direction', 'contracts', 'entryPrice', 'thesis', 'edge'];
const missing = requiredFields.filter(f => !input[f] && input[f] !== 0);

if (missing.length > 0) {
  return [{
    json: {
      error: true,
      message: `Missing required fields: ${missing.join(', ')}`,
      tradeLogged: false
    }
  }];
}

// -----------------------------------------------------------
// Generate Trade ID (PT-XXX format)
// Uses timestamp-based ID for uniqueness
// In production, read last Trade ID from sheet and increment
// -----------------------------------------------------------
const now = new Date();
const tradeNum = Math.floor(now.getTime() / 1000) % 10000;
const tradeId = `PT-${String(tradeNum).padStart(4, '0')}`;

// -----------------------------------------------------------
// Calculate DTE (Days to Expiration)
// -----------------------------------------------------------
let dte = 0;
if (input.expiration) {
  const expDate = new Date(input.expiration + 'T16:00:00');
  const today = new Date();
  today.setHours(16, 0, 0, 0);
  dte = Math.ceil((expDate - today) / (1000 * 60 * 60 * 24));
}

// -----------------------------------------------------------
// Calculate estimated max loss
// -----------------------------------------------------------
let estimatedMaxLoss = 0;
const contracts = Math.abs(input.contracts || 1);
const entryPrice = Math.abs(input.entryPrice || 0);
const strike = input.strike || 0;

switch ((input.strategy || '').toUpperCase()) {
  case 'CSP':
    // CSP max loss at stop-loss (200% of credit)
    estimatedMaxLoss = entryPrice * 2 * contracts * 100;
    break;
  case 'BULLPUTSPREAD':
  case 'BULL_PUT_SPREAD':
    // Spread max loss = (width - credit) * contracts * 100
    const spreadWidth = input.spreadWidth || 10; // Default 10-wide spread
    estimatedMaxLoss = (spreadWidth - entryPrice) * contracts * 100;
    break;
  case 'JADELIZARD':
    // Jade lizard downside = (put_strike - total_credit) * contracts * 100
    estimatedMaxLoss = (strike - entryPrice) * contracts * 100;
    break;
  case 'MOMENTUM':
  case 'EQUITY':
    // Equity max loss at -10% hard stop
    estimatedMaxLoss = strike * contracts * 0.10;
    break;
  case 'HEDGE':
    // Hedge max loss = premium paid
    estimatedMaxLoss = entryPrice * contracts * 100;
    break;
  default:
    estimatedMaxLoss = entryPrice * 2 * contracts * 100;
}

// -----------------------------------------------------------
// Estimated commission and slippage
// -----------------------------------------------------------
const isOptions = ['CSP', 'BULLPUTSPREAD', 'BULL_PUT_SPREAD', 'JADELIZARD', 'HEDGE'].includes((input.strategy || '').toUpperCase());
const commission = isOptions ? contracts * 0.65 * 2 : 0; // $0.65/contract round-trip
const slippageFactor = 0.02; // 2% of premium for liquid names
const estimatedSlippage = isOptions ? entryPrice * slippageFactor * contracts * 100 : 0;

// -----------------------------------------------------------
// Build output
// -----------------------------------------------------------
const dateStr = now.toISOString().split('T')[0];

const tradeRow = {
  tradeId: tradeId,
  dateEntry: dateStr,
  dateExit: '',
  ticker: (input.ticker || '').toUpperCase(),
  strategy: input.strategy,
  direction: input.direction,
  strike: strike,
  expiration: input.expiration || '',
  dteAtEntry: dte,
  deltaAtEntry: input.delta || 0,
  ivRankAtEntry: input.ivRank || 0,
  contracts: contracts,
  entryPrice: entryPrice,
  exitPrice: '',
  rawPnL: '',
  commission: commission.toFixed(2),
  estimatedSlippage: estimatedSlippage.toFixed(2),
  adjustedPnL: '',
  pnlPercent: '',
  daysHeld: '',
  exitReason: '',
  thesis: input.thesis || '',
  edge: input.edge || '',
  outcomeNotes: '',
  ruleCompliance: 'Yes',
  whatWouldIDoDifferently: '',
  estimatedMaxLoss: estimatedMaxLoss.toFixed(2)
};

return [{ json: tradeRow }];

// ============================================================
// Altamira Capital - Pre-Trade Risk Checks
// ============================================================
// Validates the trade against risk management framework:
//   1. Single position <= 5% of portfolio
//   2. Sector exposure <= 25%
//   3. Cash reserve >= 15%
//   4. Options allocation <= 30% notional
//   5. Max 3 correlated positions per sector
// ============================================================

const trade = $input.first().json;

// -----------------------------------------------------------
// Portfolio assumptions (paper trading starting capital)
// In production, pull these from the Daily Dashboard sheet
// or from E-Trade API balance endpoint
// -----------------------------------------------------------
const PORTFOLIO_VALUE = 100000; // $100K paper trading
const CURRENT_CASH = 20000;     // Placeholder - read from sheet
const CURRENT_OPTIONS_NOTIONAL = 0; // Placeholder - read from sheet

// -----------------------------------------------------------
// Sector mapping for core universe
// -----------------------------------------------------------
const SECTOR_MAP = {
  'AAPL': 'Technology',
  'MSFT': 'Technology',
  'GOOGL': 'Technology',
  'AMZN': 'Technology',
  'META': 'Technology',
  'NVDA': 'Technology',
  'AVGO': 'Technology',
  'V': 'Financial Services',
  'MA': 'Financial Services',
  'COST': 'Consumer Defensive',
  'SPY': 'Index'
};

const riskChecks = [];
let allPassed = true;

// -----------------------------------------------------------
// Check 1: Single position <= 5% of portfolio
// -----------------------------------------------------------
const isOptions = ['CSP', 'BULLPUTSPREAD', 'BULL_PUT_SPREAD', 'JADELIZARD', 'HEDGE'].includes((trade.strategy || '').toUpperCase());
let positionExposure = 0;

if (isOptions) {
  // For CSPs, exposure = strike * contracts * 100
  positionExposure = (trade.strike || 0) * (trade.contracts || 1) * 100;
} else {
  // For equity, exposure = price * shares
  positionExposure = (trade.strike || 0) * (trade.contracts || 1);
}

const positionPercent = (positionExposure / PORTFOLIO_VALUE) * 100;
const positionCheck = positionPercent <= 5;

riskChecks.push({
  check: 'Position Size <= 5%',
  value: `${positionPercent.toFixed(2)}%`,
  limit: '5.00%',
  passed: positionCheck
});
if (!positionCheck) allPassed = false;

// -----------------------------------------------------------
// Check 2: Sector exposure <= 25% (tech <= 35%)
// -----------------------------------------------------------
const sector = SECTOR_MAP[trade.ticker] || 'Unknown';
const sectorLimit = sector === 'Technology' ? 35 : 25;
// In production, sum all existing positions in this sector from the trade log
// For now, we check only the new position against the limit
const sectorExposure = positionPercent; // Simplified - add existing sector exposure in production
const sectorCheck = sectorExposure <= sectorLimit;

riskChecks.push({
  check: `Sector Exposure <= ${sectorLimit}% (${sector})`,
  value: `${sectorExposure.toFixed(2)}%`,
  limit: `${sectorLimit}%`,
  passed: sectorCheck
});
if (!sectorCheck) allPassed = false;

// -----------------------------------------------------------
// Check 3: Cash reserve >= 15% after trade
// -----------------------------------------------------------
let cashAfterTrade = CURRENT_CASH;
if (isOptions && (trade.direction === 'STO' || trade.direction === 'Short')) {
  // CSP ties up cash = strike * contracts * 100
  cashAfterTrade -= positionExposure;
  // Add credit received
  cashAfterTrade += (trade.entryPrice || 0) * (trade.contracts || 1) * 100;
} else if (!isOptions) {
  cashAfterTrade -= positionExposure;
}

const cashReservePercent = (cashAfterTrade / PORTFOLIO_VALUE) * 100;
const cashCheck = cashReservePercent >= 15;

riskChecks.push({
  check: 'Cash Reserve >= 15%',
  value: `${cashReservePercent.toFixed(2)}%`,
  limit: '15.00%',
  passed: cashCheck
});
if (!cashCheck) allPassed = false;

// -----------------------------------------------------------
// Check 4: Total options allocation <= 30% notional
// -----------------------------------------------------------
if (isOptions) {
  const newOptionsNotional = CURRENT_OPTIONS_NOTIONAL + positionExposure;
  const optionsPercent = (newOptionsNotional / PORTFOLIO_VALUE) * 100;
  const optionsCheck = optionsPercent <= 30;

  riskChecks.push({
    check: 'Options Allocation <= 30%',
    value: `${optionsPercent.toFixed(2)}%`,
    limit: '30.00%',
    passed: optionsCheck
  });
  if (!optionsCheck) allPassed = false;
}

// -----------------------------------------------------------
// Check 5: Max loss within tolerance
// -----------------------------------------------------------
const maxLossPercent = (parseFloat(trade.estimatedMaxLoss) / PORTFOLIO_VALUE) * 100;
const maxLossCheck = maxLossPercent <= 5; // Max 5% of portfolio per trade at stop

riskChecks.push({
  check: 'Max Loss <= 5% of Portfolio',
  value: `${maxLossPercent.toFixed(2)}% ($${parseFloat(trade.estimatedMaxLoss).toLocaleString()})`,
  limit: '5.00%',
  passed: maxLossCheck
});
if (!maxLossCheck) allPassed = false;

// -----------------------------------------------------------
// Output
// -----------------------------------------------------------
return [{
  json: {
    ...trade,
    riskChecks: riskChecks,
    allRiskChecksPassed: allPassed,
    riskCheckSummary: riskChecks.map(c => `${c.passed ? 'PASS' : 'FAIL'}: ${c.check} (${c.value} vs ${c.limit})`).join('\n')
  }
}];
